(function(){
'use strict';
function closePreview(){var m=document.getElementById('workspacePreviewModal');if(m)m.hidden=true;document.body.classList.remove('workspace-preview-open')}
function ensureModal(){var m=document.getElementById('workspacePreviewModal');if(m)return m;m=document.createElement('div');m.id='workspacePreviewModal';m.className='workspace-preview-modal';m.hidden=true;m.innerHTML='<button class="workspace-preview-backdrop" type="button" aria-label="미리보기 닫기"></button><section class="workspace-preview-dialog"><header><div><small>PREVIEW</small><b>작업화면 미리보기</b></div><button type="button" data-workspace-preview-close>×</button></header><div class="workspace-preview-viewport"><div class="workspace-preview-holder"></div></div></section>';document.body.appendChild(m);m.querySelector('.workspace-preview-backdrop').onclick=closePreview;m.querySelector('[data-workspace-preview-close]').onclick=closePreview;return m}
function openPreview(){var sheet=document.getElementById('sheet');if(!sheet)return;var m=ensureModal(),holder=m.querySelector('.workspace-preview-holder');holder.innerHTML='';var clone=sheet.cloneNode(true),cs=getComputedStyle(sheet);clone.removeAttribute('id');clone.classList.add('workspace-preview-sheet');clone.style.transform='none';clone.style.transformOrigin='top left';clone.style.margin='0';clone.style.width=cs.width;clone.style.minWidth=cs.width;clone.style.maxWidth='none';clone.style.height='auto';clone.style.minHeight=cs.minHeight;clone.style.flex='none';holder.appendChild(clone);m.hidden=false;document.body.classList.add('workspace-preview-open');requestAnimationFrame(function(){var vw=m.querySelector('.workspace-preview-viewport');vw.scrollTop=0;vw.scrollLeft=Math.max(0,(holder.scrollWidth-vw.clientWidth)/2)})}
function replaceButton(){var old=document.getElementById('previewBtn');if(!old||old.dataset.workspacePreviewReady)return;var b=old.cloneNode(true);b.dataset.workspacePreviewReady='1';old.replaceWith(b);b.addEventListener('click',function(e){e.preventDefault();e.stopPropagation();openPreview()});}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',replaceButton);else replaceButton();setTimeout(replaceButton,50);
})();